import { useState, useCallback } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Link, useNavigate } from "react-router-dom";
import styles from "../styles/auth.module.css";
import {
  signupSchema,
  type SignupSchemaType,
} from "../validations/signupSchema";
import { useAuth, detectErrorField } from "../hooks/useAuth";
import { PAKISTAN_CITIES } from "../constants/authConstants";
import { getErrorMessage } from "@shared/utils/errorHandler";
import type { ToastHook } from "../types/auth.types";

import PasswordStrength from "./PasswordStrength";
import SocialLogin from "./SocialLogin";

interface SignupFormProps {
  toast: ToastHook;
}

export default function SignupForm({ toast }: SignupFormProps) {
  const navigate = useNavigate();
  const { signup } = useAuth();

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    setError,
    clearErrors,
    formState: { errors, isSubmitting },
  } = useForm<SignupSchemaType>({
    resolver: zodResolver(signupSchema),
    defaultValues: {
      fullName: "",
      email: "",
      phone: "",
      city: "",
      password: "",
      confirmPassword: "",
      role: undefined,
      
    },
    mode: "onBlur",
  });

  const watchedPassword = watch("password");
  const watchedRole = watch("role");

  // ΓöÇΓöÇ Submit ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const onSubmit = useCallback(
    async (data: SignupSchemaType) => {
      try {
        const result = await signup(data);
        setSubmitSuccess(true);
        sessionStorage.removeItem("verify_email_resend_expiry");
        sessionStorage.removeItem("verify_email_code_expiry");
        sessionStorage.setItem("verify_email_pending_email", result.data.email);
        toast.success(
          "Account Created!",
          "Please verify your email to continue."
        );
        navigate("/verify-email", {
          state: {
            userId: result.data?.userId,
            email: result.data?.email,
            otpExpiresAt: result.data?.otpExpiresAt,
            resendAvailableAt: result.data?.resendAvailableAt,
          },
        });
      } catch (err) {
        const message = getErrorMessage(
          err,
          "Something went wrong. Please try again."
        );

        const field = detectErrorField(message);

        if (field === "email") {
          setError("email", { type: "manual", message });
          document.getElementById("email")?.focus();
        } else if (field === "password") {
          setError("password", { type: "manual", message });
        } else if (field === "phone") {
          setError("phone", { type: "manual", message });
        } else {
          setError("email", { type: "manual", message });
        }
      }
    },
    [signup, navigate, toast, setError]
  );

  const onValidationError = useCallback(() => { }, []);

  const handleInputChange = useCallback(
    (fieldName: keyof SignupSchemaType) => {
      if (errors[fieldName]?.type === "manual") {
        clearErrors(fieldName);
      }
    },
    [errors, clearErrors]
  );

  const handleGoogleClick = useCallback(() => {
    setIsGoogleLoading(true);
    const baseUrl =
      import.meta.env.VITE_API_BASE_URL ?? "http://localhost:5000/api";
    window.location.href = `${baseUrl}/auth/google`;
  }, []);



  return (
    <div className={styles.formContainer}>

      <div className={styles.formHeader}>
        <h2 className={styles.formTitle}>Create Account</h2>
        <p className={styles.formSubtitle}>
          Join Zameen 360 and start exploring properties
        </p>
      </div>

      <form
        onSubmit={handleSubmit(onSubmit, onValidationError)}
        noValidate
        autoComplete="off"
      >

        <div className={styles.formGroupRow}>

          <div className={styles.formGroup}>
            <div className={styles.inputWrapper}>
              <i
                className={`fa-solid fa-user ${styles.inputIcon}`}
                aria-hidden="true"
              />
              <input
                {...register("fullName", {
                  onChange: () => handleInputChange("fullName"),
                })}
                id="fullName"
                type="text"
                placeholder="Full Name"
                className={`${styles.formInput} ${errors.fullName ? styles.inputError : ""
                  }`}
                aria-required="true"
              />
            </div>
            {errors.fullName && (
              <p className={styles.fieldError} role="alert">
                <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
                {errors.fullName.message}
              </p>
            )}
          </div>

          {/* City */}
          <div className={styles.formGroup}>
            <div className={styles.inputWrapper}>
              <i
                className={`fa-solid fa-location-dot ${styles.inputIcon}`}
                aria-hidden="true"
              />
              <select
                {...register("city")}
                id="city"
                className={`${styles.formSelect} ${errors.city ? styles.selectError : ""
                  }`}
                aria-required="true"
              >
                <option value="">Select your city</option>
                {PAKISTAN_CITIES.map(({ value, label }) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </select>
            </div>
            {errors.city && (
              <p className={styles.fieldError} role="alert">
                <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
                {errors.city.message}
              </p>
            )}
          </div>
        </div>

        {/* ΓöÇΓöÇ Row 2: Email + Phone ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className={styles.formGroupRow}>
          <div className={styles.formGroup}>
            <div className={styles.inputWrapper}>
              <i
                className={`fa-solid fa-envelope ${styles.inputIcon}`}
                aria-hidden="true"
              />
              <input
                {...register("email", {
                  onChange: () => handleInputChange("email"),
                })}
                id="email"
                type="email"
                placeholder="Email Address"
                className={`${styles.formInput} ${errors.email ? styles.inputError : ""
                  }`}
                aria-required="true"
              />
            </div>
            {errors.email && (
              <p className={styles.fieldError} role="alert">
                <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
                {errors.email.message}
              </p>
            )}
          </div>

          <div className={styles.formGroup}>
            <div className={`${styles.inputWrapper} ${styles.phoneInputWrapper}`}>
              <div className={styles.countryPrefix}>
                <span className={styles.flag}>≡ƒç╡≡ƒç░</span>
                <span className={styles.code}>+92</span>
              </div>
              <input
                {...register("phone", {
                  onChange: (e) => {
                    handleInputChange("phone");
                    let val = e.target.value;
                    val = val.replace(/\D/g, ""); // Keep only digits
                    if (val.startsWith("92") && val.length > 10) {
                      val = val.substring(2);
                    }
                    if (val.startsWith("0")) {
                      val = val.substring(1);
                    }
                    if (val.length > 10) {
                      val = val.substring(0, 10);
                    }
                    setValue("phone", val, { shouldValidate: true });
                  },
                })}
                id="phone"
                type="tel"
                placeholder="300 1234567"
                className={`${styles.formInput} ${styles.phoneInput} ${errors.phone ? styles.inputError : ""
                  }`}
                aria-required="true"
              />
            </div>
            {errors.phone && (
              <p className={styles.fieldError} role="alert">
                <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
                {errors.phone.message}
              </p>
            )}
          </div>
        </div>

        {/* ΓöÇΓöÇ Row 3: Password + Confirm ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className={styles.formGroupRow}>
          <div className={styles.formGroup}>
            <div className={styles.inputWrapper}>
              <i
                className={`fa-solid fa-lock ${styles.inputIcon}`}
                aria-hidden="true"
              />
              <input
                {...register("password", {
                  onChange: () => handleInputChange("password"),
                })}
                id="password"
                type={showPassword ? "text" : "password"}
                placeholder="Password"
                className={`${styles.formInput} ${styles.passwordInput} ${errors.password ? styles.inputError : ""
                  }`}
                aria-required="true"
              />
              <button
                type="button"
                className={styles.passwordToggle}
                onClick={() => setShowPassword((p) => !p)}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                <i
                  className={`fa-solid ${showPassword ? "fa-eye-slash" : "fa-eye"
                    }`}
                  aria-hidden="true"
                />
              </button>
            </div>
            <PasswordStrength password={watchedPassword} />
            {errors.password && (
              <p className={styles.fieldError} role="alert">
                <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
                {errors.password.message}
              </p>
            )}
          </div>

          <div className={styles.formGroup}>
            <div className={styles.inputWrapper}>
              <i
                className={`fa-solid fa-lock ${styles.inputIcon}`}
                aria-hidden="true"
              />
              <input
                {...register("confirmPassword")}
                id="confirmPassword"
                type={showConfirm ? "text" : "password"}
                placeholder="Confirm Password"
                className={`${styles.formInput} ${styles.passwordInput} ${errors.confirmPassword ? styles.inputError : ""
                  }`}
                aria-required="true"
              />
              <button
                type="button"
                className={styles.passwordToggle}
                onClick={() => setShowConfirm((p) => !p)}
                aria-label={showConfirm ? "Hide password" : "Show password"}
              >
                <i
                  className={`fa-solid ${showConfirm ? "fa-eye-slash" : "fa-eye"
                    }`}
                  aria-hidden="true"
                />
              </button>
            </div>
            {errors.confirmPassword && (
              <p className={styles.fieldError} role="alert">
                <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
                {errors.confirmPassword.message}
              </p>
            )}
          </div>
        </div>

        {/* ΓöÇΓöÇ Role Cards ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className={styles.roleSection}>
          <label className={styles.roleSectionLabel}>
            I am a <span className={styles.required}>*</span>
          </label>
          <div
            className={styles.roleCards}
            role="radiogroup"
            aria-label="Select your role"
          >
            {(
              [
                { value: "buyer", icon: "fa-user", label: "Buyer" },
                { value: "seller", icon: "fa-house", label: "Seller" },
              ] as const
            ).map(({ value, icon, label }) => (
              <label
                key={value}
                className={[
                  styles.roleCard,
                  watchedRole === value ? styles.roleCardSelected : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                tabIndex={0}
                onKeyDown={(e: React.KeyboardEvent) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setValue("role", value, { shouldValidate: true });
                  }
                }}
              >
                <input
                  {...register("role")}
                  type="radio"
                  value={value}
                  className={styles.hiddenRadio}
                  aria-label={label}
                />
                <div className={styles.roleIconWrap}>
                  <i
                    className={`fa-solid ${icon} ${styles.roleIcon}`}
                    aria-hidden="true"
                  />
                </div>
                <span className={styles.roleText}>{label}</span>
              </label>
            ))}
          </div>
          {errors.role && (
            <p className={styles.fieldError} role="alert">
              <i className="fa-solid fa-circle-exclamation" aria-hidden="true" />
              {errors.role.message}
            </p>
          )}
        </div>

        {/* ΓöÇΓöÇ Submit ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <button
          type="submit"
          className={[
            styles.submitBtn,
            isSubmitting ? styles.submitBtnLoading : "",
          ]
            .filter(Boolean)
            .join(" ")}
          disabled={isSubmitting}
          aria-label="Create your account"
        >
          {submitSuccess ? (
            <>
              <i className="fa-solid fa-check" aria-hidden="true" />
              <span>Registered!</span>
            </>
          ) : isSubmitting ? (
            <>
              <div className={styles.spinner} aria-hidden="true" />
              <span>Registering...</span>
            </>
          ) : (
            <span>Register</span>
          )}
        </button>

        {/* ΓöÇΓöÇ Social Login ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <SocialLogin
          onGoogleClick={handleGoogleClick}
          isLoading={isGoogleLoading}
        />

        <p className={styles.formFooter}>
          Already have an account? <Link to="/login">Login</Link>
        </p>
      </form>
    </div>
  );
}

import axios from "axios";
import type {
  AxiosInstance,
  InternalAxiosRequestConfig,
  AxiosResponse,
  AxiosError,
} from "axios";
import { STORAGE_KEYS } from "@features/auth/constants/authConstants";

interface ApiErrorShape {
  message: string;
  status: number | undefined;
  requiresVerification?: boolean;
  raw: AxiosError;
}

const axiosInstance: AxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL ?? "http://localhost:5000/api",
  headers: {
    "Content-Type": "application/json",
    Accept: "application/json",
  },
});

axiosInstance.interceptors.request.use(
  (config: InternalAxiosRequestConfig): InternalAxiosRequestConfig => {
    const token = localStorage.getItem(STORAGE_KEYS.TOKEN);

    if (token && config.headers) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    if (config.data instanceof FormData && config.headers) {
      delete config.headers["Content-Type"];
    }

    return config;
  },
  (error: AxiosError) => Promise.reject(error),
);

axiosInstance.interceptors.response.use(
  (response: AxiosResponse) => response.data,

  (error: AxiosError<{ message?: string; requiresVerification?: boolean }>) => {
    const message =
      error.response?.data?.message ?? error.message ?? "Something went wrong.";

    const status = error.response?.status;

    const requiresVerification =
      typeof error.response?.data === "object" &&
      error.response?.data !== null &&
      "requiresVerification" in error.response.data
        ? Boolean((error.response.data as any).requiresVerification)
        : undefined;

    // Auto logout on 401 (but not for login/register)
    const url = error.config?.url || "";
    const isAuthRequest = url.includes("/login") || url.includes("/register");

    if (status === 401 && !isAuthRequest) {
      localStorage.removeItem(STORAGE_KEYS.TOKEN);
      localStorage.removeItem(STORAGE_KEYS.USER);
      window.location.href = "/login";
    }

    const apiError: ApiErrorShape = {
      message,
      status,
      requiresVerification,
      raw: error,
    };

    return Promise.reject(apiError);
  },
);

export default axiosInstance;
